package com.justjava.humanresource.employeeexit.workflow.delegate; import com.justjava.humanresource.employeeexit.service.EmployeeExitService; import com.justjava.humanresource.employeeexit.service.ExitAssetSnapshotService; import lombok.RequiredArgsConstructor; import org.flowable.engine.delegate.*; import org.springframework.stereotype.Component;
@Component("initializeExitClearanceDelegate") @RequiredArgsConstructor public class InitializeExitClearanceDelegate implements JavaDelegate {private final EmployeeExitService service;private final ExitAssetSnapshotService assets;public void execute(DelegateExecution e){Long id=((Number)e.getVariable("exitCaseId")).longValue();service.initializeClearance(id);assets.snapshotAssignedAssets(id);var x=service.require(id);e.setVariable("exitEffectiveAt",java.util.Date.from(x.getEffectiveExitDate().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant()));}}
